#include <iostream>
#include <string>

using namespace std;

string n;
int num[12];
long long jc[25];
long long ans;
int temNum[12];

void dfs(int x) {
    if (x == 10) {
        int cnt = 0;
        for (int i = 0; i < 10; i++)
            cnt += temNum[i];

        long long temAns = jc[cnt];
        for (int i = 0; i < 10; i++)
            if (temNum[i] > 0)
                temAns /= jc[temNum[i]];

        temAns -= temAns * temNum[0] / cnt;
        ans += temAns;
        return;
    }

    if (num[x] == 0) {
        temNum[x] = 0;
        dfs(x + 1);
    } else {
        for (int i = 1; i <= num[x]; i++) {
            temNum[x] = i;
            dfs(x + 1);
        }
    }
}

int main() {
    cin >> n;

    for (char c : n)
        num[c - '0']++;

    jc[0] = 1;
    for (int i = 1; i <= 20; i++)
        jc[i] = jc[i - 1] * i;

    dfs(0);
    cout << ans << '\n';

    return 0;
}

